llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Niraparib absolute oral bioavailability was 72.7% (90% CI 61.69–83.40) in six cancer patients after a 300 mg oral dose versus IV 14C-niraparib, directly supporting F ≥20%."
    },
    {
      "card_ids": ["C07"],
      "claim": "Flecainide absolute oral bioavailability averaged 70% (range 60–86%) in ten healthy subjects after oral 200 mg versus IV 2 mg/kg, directly supporting F ≥20%."
    },
    {
      "card_ids": ["C49"],
      "claim": "Tasimelteon absolute bioavailability was 38.33% (90% CI 26.94–54.33) in 14 subjects based on dose-corrected AUC versus IV, directly supporting F ≥20%."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": [],
  "decision_summary": "Most transferred evidence, including direct absolute measurements for niraparib (72.7%), flecainide (70%), and tasimelteon (38.3%), supports F ≥20%; didanosine adult absolute F ~43% also supports high despite some low pediatric/fed-condition values.",
  "evidence_gaps": [
    "Didanosine has variable reported bioavailability, including low pediatric/fed-condition values (13–19%), although its strongest adult absolute measurement is ~43%; this variability adds uncertainty.",
    "Some evidence molecules (anle138b, risdiplam, ethionamide) report only qualitative high/excellent bioavailability without numeric absolute F values."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C54", "C07", "C49"],
  "revision_action": "initial",
  "supportive_card_ids": ["C54", "C07", "C49"]
}

